import {run} from './runtime.js';
import * as THREE from './three.module.js';
const $=id=>document.getElementById(id);
let renderer;
try{renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});}catch(e){$('begin').disabled=true;$('begin').textContent='WEBGL REQUIRED';throw e;}
renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;$('world').appendChild(renderer.domElement);
const scene=new THREE.Scene();scene.background=new THREE.Color(0x151b1c);scene.fog=new THREE.FogExp2(0x30312b,.011);
const camera=new THREE.PerspectiveCamera(65,innerWidth/innerHeight,.1,300);camera.position.set(0,2,25);
scene.add(new THREE.HemisphereLight(0x9eb4bb,0x4b3320,1.8));const moon=new THREE.DirectionalLight(0xb5cbd0,2);moon.position.set(-30,60,-50);moon.castShadow=true;moon.shadow.mapSize.set(2048,2048);Object.assign(moon.shadow.camera,{left:-70,right:70,top:70,bottom:-70,far:180});scene.add(moon);
const sand=new THREE.MeshStandardMaterial({color:0x746853,roughness:1});const stone=new THREE.MeshStandardMaterial({color:0x746f60,roughness:1});const black=new THREE.MeshStandardMaterial({color:0x20282a,metalness:.7,roughness:.35});const gold=new THREE.MeshStandardMaterial({color:0xe4c78d,metalness:.8,roughness:.25,emissive:0xbc7b2c,emissiveIntensity:.6});
function terrain(x,z){return Math.sin(x*.07)*1.5+Math.cos(z*.08)*1.3+Math.sin(x*.13+z*.09)*.5;}
const groundGeo=new THREE.PlaneGeometry(280,280,140,140);groundGeo.rotateX(-Math.PI/2);const pa=groundGeo.attributes.position;for(let i=0;i<pa.count;i++)pa.setY(i,terrain(pa.getX(i),pa.getZ(i)));groundGeo.computeVertexNormals();const ground=new THREE.Mesh(groundGeo,sand);ground.receiveShadow=true;scene.add(ground);
const obstacles=[];
function block(x,z,w,h,d,mat=stone,collision=true){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);m.position.set(x,terrain(x,z)+h/2,z);m.castShadow=true;m.receiveShadow=true;scene.add(m);if(collision)obstacles.push({x,z,w:w/2+.45,d:d/2+.45});return m;}
let seed=77;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;}
for(let i=0;i<100;i++){let x=(rand()-.5)*220,z=(rand()-.5)*220;if(Math.hypot(x,z)<45)continue;let geo=new THREE.ConeGeometry(7+rand()*15,14+rand()*32,5);let m=new THREE.Mesh(geo,stone);m.position.set(x,terrain(x,z)+6,z);m.rotation.y=rand()*6;scene.add(m);}
// Broken temple: a processional path through monumental ruins.
for(let i=0;i<8;i++){const z=20-i*9;for(const x of [-13,13]){if(rand()>.18){const h=6+rand()*7;block(x,z,2.2,h,2.2);block(x,z,3.4,.65,3.4,stone,false).position.y=terrain(x,z)+h;}}}
block(-13,-34,5,3,15);block(13,-5,5,3,9);block(-5,-17,6,2.2,3);block(7,-40,6,2.7,3);block(0,-61,28,3,3);block(-24,0,6,4,7);
for(let i=0;i<45;i++){let x=(rand()-.5)*85,z=25-rand()*100;if(Math.abs(x)<5)continue;const m=block(x,z,1+rand()*2,.5+rand()*1.4,1+rand()*2,stone,false);m.rotation.set(rand()*.3,rand()*6,rand()*.3);}
// Distant ring suspended above the mountain.
const ring=new THREE.Mesh(new THREE.TorusGeometry(10,.14,12,160),gold);ring.position.set(2,25,-76);ring.rotation.x=.25;scene.add(ring);const innerRing=ring.clone();innerRing.scale.setScalar(.85);innerRing.rotation.y=.7;scene.add(innerRing);
const bush=new THREE.Group();bush.position.set(0,terrain(0,-53),-53);scene.add(bush);for(let i=0;i<28;i++){const branch=new THREE.Mesh(new THREE.CylinderGeometry(.025,.12,2+rand()*2,5),black);branch.rotation.z=(rand()-.5)*2;branch.rotation.x=(rand()-.5)*1.5;branch.position.set((rand()-.5)*2,1.4,(rand()-.5)*2);bush.add(branch);}const fire=new THREE.PointLight(0xff8b2c,30,35,1.5);fire.position.set(0,3,0);bush.add(fire);
const emberGeo=new THREE.BufferGeometry();const embers=new Float32Array(240*3);for(let i=0;i<240;i++){embers[i*3]=(rand()-.5)*4;embers[i*3+1]=rand()*7;embers[i*3+2]=(rand()-.5)*4;}emberGeo.setAttribute('position',new THREE.BufferAttribute(embers,3));const sparks=new THREE.Points(emberGeo,new THREE.PointsMaterial({color:0xffbd64,size:.12,transparent:true,opacity:.85,blending:THREE.AdditiveBlending}));bush.add(sparks);
const beam=new THREE.Mesh(new THREE.CylinderGeometry(.14,.8,55,24,1,true),new THREE.MeshBasicMaterial({color:0xf1b866,transparent:true,opacity:.08,side:THREE.DoubleSide,depthWrite:false}));beam.position.set(0,27,-53);scene.add(beam);
const locations=[[-7,18],[-23,5],[21,-8],[-22,-19],[20,-33],[-20,-43],[8,-51]];const fragments=locations.map(([x,z],i)=>{const g=new THREE.Group();g.position.set(x,terrain(x,z),z);const altar=block(x,z,2,1,2,black);const m=new THREE.Mesh(new THREE.OctahedronGeometry(.6),gold);m.position.y=2.5;g.add(m);const halo=new THREE.Mesh(new THREE.TorusGeometry(1,.018,6,60),gold);halo.rotation.x=Math.PI/2;halo.position.y=1.5;g.add(halo);const light=new THREE.PointLight(0xffcc74,5,13);light.position.y=3;g.add(light);scene.add(g);return{g,m,halo,x,z,taken:false};});
const watchers=[[-5,3],[7,-22],[-6,-40]].map(([x,z],i)=>{const g=new THREE.Group();const body=new THREE.Mesh(new THREE.OctahedronGeometry(1.1,0),black);body.scale.y=2.7;g.add(body);const eye=new THREE.Mesh(new THREE.SphereGeometry(.2,12,12),new THREE.MeshBasicMaterial({color:0xff4132}));eye.position.set(0,.4,1);g.add(eye);const light=new THREE.PointLight(0xef3929,5,16);g.add(light);const cone=new THREE.Mesh(new THREE.ConeGeometry(5,15,32,1,true),new THREE.MeshBasicMaterial({color:0xec4433,transparent:true,opacity:.045,depthWrite:false,side:THREE.DoubleSide}));cone.rotation.x=-Math.PI/2;cone.position.z=8;g.add(cone);scene.add(g);return{g,x,z,phase:i*2};});
const dustGeo=new THREE.BufferGeometry();const dust=new Float32Array(1300*3);for(let i=0;i<dust.length;i+=3){dust[i]=(rand()-.5)*160;dust[i+1]=rand()*25;dust[i+2]=(rand()-.5)*160;}dustGeo.setAttribute('position',new THREE.BufferAttribute(dust,3));scene.add(new THREE.Points(dustGeo,new THREE.PointsMaterial({color:0xd1b98b,size:.045,transparent:true,opacity:.45})));

run({renderer,scene,camera,terrain,obstacles,fragments,watchers,ring,innerRing,bush,fire,embers,emberGeo,stone,gold,black});
